<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Http\Request; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\DeliveryLog; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Incident; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\IncidentEvent;
class ComparisonReportController { public function __invoke(Request $r){$days=max(1,min(90,$r->integer('days',7)));$since=now()->subDays($days);$metrics=['incidents_generated'=>Incident::where('created_at','>=',$since)->count(),'alerts_received'=>IncidentEvent::where('event_type','received')->where('created_at','>=',$since)->count(),'would_send'=>DeliveryLog::where('status','dry_run')->where('created_at','>=',$since)->count(),'sent'=>DeliveryLog::where('status','sent')->where('created_at','>=',$since)->count(),'suppressed'=>IncidentEvent::where('event_type','suppressed')->where('created_at','>=',$since)->count(),'missing_receivers'=>IncidentEvent::where('event_type','notification_failed')->where('event_message','like','No notification receiver%')->where('created_at','>=',$since)->count(),'processing_errors'=>DeliveryLog::whereIn('status',['failed','failed_configuration'])->where('created_at','>=',$since)->count(),'missing_policies'=>Incident::where('suppression_reason','no_policy')->where('updated_at','>=',$since)->count()];return view('iapm::comparison-report',compact('metrics','days'));} }
